mapper.select:
select a.album_id, a.member_id, a.product_id, a.title, a.travel_date, a.cover, a.media_json, a.description, a.status, a.create_time, a.update_time, m.nickname as member_name, p.title as product_title from hys_album a left join hys_member m on m.member_id = a.member_id left join hys_product p on p.product_id = a.product_id
and a.member_id = #{memberId} and a.title like concat('%', #{title}, '%') and a.status = #{status}
order by a.travel_date desc, a.album_id desc

mapper.update:
update hys_album
member_id = #{memberId}, product_id = #{productId}, title = #{title}, travel_date = #{travelDate}, cover = #{cover}, media_json = #{mediaJson}, description = #{description}, status = #{status}, update_time = now()
where album_id = #{albumId}
